229	    /**
230	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
231	     * The address is normalized in place (so a required-field check that follows rejects an
232	     * address blank after normalization), the required fields are checked, the telephone and
233	     * email are normalized in place, and the resulting telephone is rejected when it already
234	     * belongs to another owner. Each rule
235	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
236	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
237	     * to be mapped and saved.
238	     *
239	     * @param ownerFieldsDto the submitted owner fields, normalized in place
240	     */
241	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
242	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
243	        validateRequiredFields(ownerFieldsDto);
244	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
245	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
246	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
247	        rejectDuplicateHousehold(ownerFieldsDto);
248	        rejectCityAtCapacity(ownerFieldsDto.getCity());
249	        rejectDailyLimitExceeded(registrationDate);
250	    }
251	
252	    /**
253	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
254	     * falls on a business day. The date supplied on the request is used when present, otherwise the
255	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
256	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
257	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
258	     * membership number's year segment, the per-day create limit) is computed against.
259	     *
260	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
261	     * @return the effective registration date rolled forward to the next business day
262	     */
263	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
264	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
265	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
266	        return toBusinessDay(effective);
267	    }
268	
269	    /**
270	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
271	     * following Monday, while a weekday is returned unchanged.
272	     *
273	     * @param date the date to adjust
274	     * @return the same date when it is a weekday, otherwise the next Monday
275	     */
276	    private LocalDate toBusinessDay(LocalDate date) {
277	        java.time.DayOfWeek day = date.getDayOfWeek();
278	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
279	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
280	        }
281	        return date;
282	    }
283	
284	    /**
285	     * The maximum number of owners that may be created on a single day. Once this many owners
286	     * already carry today's {@code registrationDate}, no further owner may be created today.
287	     */
288	    private static final long DAILY_OWNER_LIMIT = 100L;
289	
290	    /**
291	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
292	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
293	     * date the new owner would be stored with, so owners are capped per business day. When the limit
294	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
295	     * advice renders as a 429 Too Many Requests response.
296	     *
297	     * @param registrationDate the adjusted business-day registration date of the owner being created
298	     */
299	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
300	        long count = this.clinicService.findAllOwners().stream()
301	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
302	            .count();
303	        if (count >= DAILY_OWNER_LIMIT) {
304	            throw new DailyOwnerLimitExceededException(registrationDate);
305	        }
306	    }
307	
308	    /**
309	     * The number of owners that may carry a single day's {@code registrationDate} before that day
310	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
311	     * the create and read responses report {@code bulkSignupWarning} true for that date.
312	     */
313	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
314	
315	    /**
316	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
317	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
318	     * count is taken against the same adjusted date owners are stored with, mirroring the
319	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
320	     *
321	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
322	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
323	     */
324	    private boolean bulkSignupWarning(LocalDate registrationDate) {
325	        if (registrationDate == null) {
326	            return false;
327	        }
328	        long count = this.clinicService.findAllOwners().stream()
329	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
330	            .count();
331	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
332	    }
333	
334	    /**
335	     * The maximum number of owners a single city may hold. Once a city already contains this
336	     * many owners, no further owner may be created in it.
337	     */
338	    private static final long CITY_OWNER_CAPACITY = 50L;
339	
340	    /**
341	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
342	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
343	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
344	     * which the exception advice renders as a 409 Conflict response.
345	     *
346	     * @param city the city of the owner being created
347	     */
348	    private void rejectCityAtCapacity(String city) {
349	        long count = this.clinicService.findAllOwners().stream()
350	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
351	            .count();
352	        if (count >= CITY_OWNER_CAPACITY) {
353	            throw new CityCapacityExceededException(city);
354	        }
355	    }
356	
357	    /**
358	     * Builds the customer code assigned to a newly created owner. The code is formatted as
359	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three letters
360	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
361	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
362	     * number of owners already in that city. For example the seventh owner in {@code 'Springfield'}
363	     * named {@code 'Smith'} is assigned {@code 'SPR-SMI-0007'}.
364	     *
365	     * @param city the owner's city
366	     * @param lastName the owner's last name
367	     * @return the formatted customer code
368	     */
369	    private String nextCustomerCode(String city, String lastName) {
370	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
371	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
372	        long sequence = this.clinicService.findAllOwners().stream()
373	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
374	            .count() + 1L;
375	        return String.format("%s-%s-%04d", city3, last3, sequence);
376	    }
377	
378	    /**
379	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
380	     * with the owner being created, compared case-insensitively. The count is taken before the
381	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
382	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
383	     *
384	     * @param firstName the first name of the owner being created
385	     * @param lastName the last name of the owner being created
386	     * @return the number of pre-existing owners sharing the same first and last name
387	     */
388	    private int countNamesakes(String firstName, String lastName) {
389	        return (int) this.clinicService.findAllOwners().stream()
390	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
391	                && lastName.equalsIgnoreCase(existing.getLastName()))
392	            .count();
393	    }
394	
395	    /**
396	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
397	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
398	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
399	     * the names of every offending field, which the exception advice renders as a 400 response
400	     * with an {@code errors} array.
401	     *
402	     * @param ownerFieldsDto the submitted owner fields
403	     */
404	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
405	        List<String> missing = new ArrayList<>();
406	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
407	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
408	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
409	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
410	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
411	        if (!missing.isEmpty()) {
412	            throw new RequiredFieldsMissingException(missing);
413	        }
414	    }
415	
416	    private void addIfBlank(List<String> missing, String fieldName, String value) {
417	        if (value == null || value.isBlank()) {
418	            missing.add(fieldName);
419	        }
420	    }
421	
422	    /**
423	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
424	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
425	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
426	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
427	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
428	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
429	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
430	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
431	     *
432	     * @param telephone the submitted telephone value
433	     * @return the normalized E.164 telephone
434	     */
435	    private String normalizeTelephone(String telephone) {
436	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
437	        String e164;
438	        if (cleaned.startsWith("+")) {
439	            e164 = "+" + cleaned.substring(1);
440	        } else {
441	            String national = cleaned;
442	            if (national.startsWith("0")) {
443	                national = national.substring(1);
444	            }
445	            e164 = "+61" + national;
446	        }
447	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
448	            throw new InvalidFieldsException(List.of("telephone"));
449	        }
450	        return e164;
451	    }
452	
453	    /**
454	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
455	     * and a domain containing at least one dot, none of the parts holding whitespace or a
456	     * second {@code @}.
457	     */
458	    private static final java.util.regex.Pattern EMAIL_PATTERN =
459	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
460	
461	    /**
462	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
463	     * accepted and returned unchanged. When present it must be a syntactically valid address;
464	     * the value is stored and returned lower-cased. When present but invalid an
465	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
466	     * response naming the {@code email} field.
467	     *
468	     * @param email the submitted email value, or {@code null} when omitted
469	     * @return the lower-cased email, or {@code null} when none was supplied
470	     */
471	    private String normalizeEmail(String email) {
472	        if (email == null) {
473	            return null;
474	        }
475	        String trimmed = email.trim();
476	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
477	            throw new InvalidFieldsException(List.of("email"));
478	        }
479	        return trimmed.toLowerCase(java.util.Locale.ROOT);
480	    }
481	
482	    /**
483	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
484	     * The telephone is stored in its normalized E.164 form, so a plain equality check
485	     * against every owner's telephone compares E.164 values. When a match is found a
486	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
487	     * 409 Conflict response.
488	     *
489	     * @param telephone the normalized telephone of the owner being created
490	     */
491	    private void rejectDuplicateTelephone(String telephone) {
492	        boolean taken = this.clinicService.findAllOwners().stream()
493	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
494	        if (taken) {
495	            throw new DuplicateTelephoneException(telephone);
496	        }
497	    }
498	
499	    /**
500	     * Rejects a new owner whose {@code lastName} and {@code address} already belong to another
501	     * owner, i.e. one that shares its household (see {@link #findHouseholdMate(String, String)}
502	     * for how that identity is compared). A request may bypass this rule by setting
503	     * {@code sharesHousehold} to {@code true}, allowing several owners to share one household.
504	     * When a household mate is found and the request did not opt in a
505	     * {@link DuplicateHouseholdException} is thrown, which the exception advice renders as a 409
506	     * Conflict response.
507	     *
508	     * @param ownerFieldsDto the submitted owner fields
509	     */
510	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
511	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
512	            return;
513	        }
514	        boolean taken = findHouseholdMate(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()).isPresent();
515	        if (taken) {
516	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
517	        }
518	    }
519	
520	    /**
521	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
522	     * set to {@code true}. The identifier is derived deterministically from the owner's
523	     * household identity (its {@code lastName} and {@code address}, see
524	     * {@link #householdIdFor(String, String)}), so every owner in the same household resolves to
525	     * the same stable value. The new owner receives that value, and any existing household mates
526	     * that do not yet carry it are updated so the whole household shares one identifier. When the
527	     * request did not opt in the owner is left without a household identifier.
528	     *
529	     * @param owner the newly created owner, mutated in place with its household identifier
530	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
531	     */
532	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
533	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
534	            return;
535	        }
536	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
537	        owner.setHouseholdId(householdId);
538	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
539	            if (!householdId.equals(mate.getHouseholdId())) {
540	                mate.setHouseholdId(householdId);
541	                this.clinicService.saveOwner(mate);
542	            }
543	        }
544	    }
545	
546	    /**
547	     * Derives the stable {@code householdId} shared by every owner in the household identified by
548	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
549	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
550	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
551	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
552	     *
553	     * @param lastName the household's last name
554	     * @param address the household's address
555	     * @return the deterministic household identifier
556	     */
557	    private String householdIdFor(String lastName, String address) {
558	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
559	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
560	        try {
561	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
562	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
563	            StringBuilder sb = new StringBuilder();
564	            for (int i = 0; i < 8; i++) {
565	                sb.append(String.format("%02X", digest[i]));
566	            }
567	            return "HH-" + sb;
568	        }
569	        catch (java.security.NoSuchAlgorithmException e) {
570	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
571	        }
572	    }
573	
574	    /**
575	     * Finds an existing owner that shares a household with the given {@code lastName} and
576	     * {@code address}. When several owners match, the first one encountered is returned.
577	     *
578	     * @param lastName the last name to match on
579	     * @param address the address to match on
580	     * @return the first owner sharing the household, or empty when none exists
581	     */
582	    private Optional<Owner> findHouseholdMate(String lastName, String address) {
583	        return findHouseholdMates(lastName, address).stream().findFirst();
584	    }
585	
586	    /**
587	     * Finds every existing owner that shares a household with the given {@code lastName} and
588	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
589	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
590	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
591	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
592	     * every rule that reasons about households.
593	     *
594	     * @param lastName the last name to match on
595	     * @param address the address to match on
596	     * @return the owners sharing the household, in encounter order (possibly empty)
597	     */
598	    private List<Owner> findHouseholdMates(String lastName, String address) {
599	        String normalizedLastName = collapseWhitespace(lastName);
600	        String normalizedAddress = normalizeAddress(address);
601	        return this.clinicService.findAllOwners().stream()
602	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
603	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
604	            .toList();
605	    }
606	
607	    /**
608	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
609	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
610	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
611	     *
612	     * @param value the value to collapse, or {@code null}
613	     * @return the whitespace-collapsed value, never {@code null}
614	     */
615	    private String collapseWhitespace(String value) {
616	        if (value == null) {
617	            return "";
618	        }
619	        return value.trim().replaceAll("\\s+", " ");
620	    }
621	
622	    /**
623	     * Common street-type abbreviations expanded during address normalization, keyed by their
624	     * upper-cased token.
625	     */
626	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
627	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
628	
629	    /**
630	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
631	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
632	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
633	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
634	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
635	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
636	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
637	     * everywhere an address is stored or compared.
638	     *
639	     * @param address the submitted address value, or {@code null}
640	     * @return the normalized address, never {@code null}
641	     */
642	    private String normalizeAddress(String address) {
643	        if (address == null) {
644	            return "";
645	        }
646	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
647	        if (collapsed.isEmpty()) {
648	            return "";
649	        }
650	        String[] tokens = collapsed.split(" ");
651	        StringBuilder sb = new StringBuilder(collapsed.length());
652	        for (int i = 0; i < tokens.length; i++) {
653	            if (i > 0) {
654	                sb.append(' ');
655	            }
656	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
657	        }
658	        return sb.toString();
659	    }
660	}
